{"code": "# Verify no dead links remain
import re, glob

wiki_path = "/home/zhouhuijuan1987/wiki/youtube-video-research-wiki"

file_index = set()
for f in glob.glob(f"{wiki_path}/wiki/**/*.md", recursive=True):
    name = f.replace(wiki_path + "/wiki/", "").rsplit(".md", 1)[0].lower()
    file_index.add(name)
    short_name = name.split("/")[-1].lower()
    file_index.add(short_name)

dead_links = []
for f in glob.glob(f"{wiki_path}/wiki/**/*.md", recursive=True):
    with open(f) as fh:
        content = fh.read()
    rel_name = f.replace(wiki_path + "/wiki/", "")
    for link in re.findall(r'\[\[([^\]]+?)(?:\|[^\]]+)?\]\]', content):
        link_stripped = link.strip()
        matched = False
        for entry in file_index:
            if link_stripped.lower() == entry or link_stripped.lower() == entry.split("/")[-1]:
                matched = True
                break
        if not matched:
            dead_links.append((rel_name, link_stripped))

if dead_links:
    print(f"❌ {len(dead_links)} remaining dead links:")
    for f, link in dead_links:
        print(f"  [{f}] [[{link}]]")
else:
    print(f"✅ No dead links! All wikilinks valid.")
